package com.kampotourism.settings;
import com.fasterxml.jackson.databind.JsonNode; import jakarta.persistence.*; import java.time.Instant; import org.hibernate.annotations.JdbcTypeCode; import org.hibernate.annotations.UpdateTimestamp; import org.hibernate.type.SqlTypes;
@Entity @Table(name="site_setting") public class SiteSetting {@Id private String settingKey; @JdbcTypeCode(SqlTypes.JSON) @Column(nullable=false) private JsonNode value; @UpdateTimestamp private Instant updatedAt; @Version private long version; protected SiteSetting(){} SiteSetting(String key,JsonNode value){settingKey=key;this.value=value;} void setValue(JsonNode value){this.value=value;} public String getSettingKey(){return settingKey;} public JsonNode getValue(){return value;} public Instant getUpdatedAt(){return updatedAt;} public long getVersion(){return version;}}
